// ---------- begin Matrix ----------

class SquareMatrix {
    constructor(n, a) {
        this.n = n;
        this.a = a;
    }

    static zero(n) {
        const z = ModInt.zero();
        const a = Array(n * n).fill(z);
        return new SquareMatrix(n, a);
    }

    static identity(n) {
        const m = SquareMatrix.zero(n);
        for (let i = 0; i < n; i++) {
            m.a[i * n + i] = ModInt.one();
        }
        return m;
    }

    set_at(i, j, v) {
        this.a[i * this.n + j] = v;
    }

    get_at(i, j) {
        return this.a[i * this.n + j];
    }

    static matmul(l, r) {
        return l.mul(r);
    }

    add(rhs) {
        const n = this.n;
        const c = SquareMatrix.zero(n);
        for (let i = 0; i < n * n; i++) {
            c.a[i] = this.a[i].add(rhs.a[i]);
        }
        return c;
    }

    mul(rhs) {
        const n = this.n;
        const c = SquareMatrix.zero(n);
        for (let i = 0; i < n; i++) {
            for (let k = 0; k < n; k++) {
                const a = this.a[i * n + k];
                for (let j = 0; j < n; j++) {
                    const idxC = i * n + j;
                    const idxR = k * n + j;
                    c.a[idxC] = c.a[idxC].add(a.mul(rhs.a[idxR]));
                }
            }
        }
        return c;
    }
}

// ---------- end Matrix ----------
// ---------- begin ModInt ----------

const MOD = 1000000007;

class ModInt {
    constructor(v) {
        this.v = v % MOD;
    }

    static new(v) {
        return new ModInt(v);
    }

    static zero() {
        return new ModInt(0);
    }

    static one() {
        return new ModInt(1);
    }

    add(other) {
        let d = this.v + other.v;
        if (d >= MOD) d -= MOD;
        return new ModInt(d);
    }

    sub(other) {
        let d = this.v + MOD - other.v;
        if (d >= MOD) d -= MOD;
        return new ModInt(d);
    }

    mul(other) {
        const res = (BigInt(this.v) * BigInt(other.v)) % BigInt(MOD);
        return new ModInt(Number(res));
    }

    divNum(other) {
        return this.mul(ModInt.new(other).pow(MOD - 2));
    }

    div(other) {
        return this.mul(other.pow(MOD - 2));
    }

    neg() {
        return new ModInt(this.v === 0 ? 0 : MOD - this.v);
    }

    pow(n) {
        let t = ModInt.new(1);
        let s = this;
        let e = n;
        while (e > 0) {
            if ((e & 1) === 1) {
                t = t.mul(s);
            }
            s = s.mul(s);
            e >>= 1;
        }
        return t;
    }

    toString() {
        return String(this.v);
    }
}

class Precalc {
    constructor(n) {
        this.n = n;
        this.inv = Array(n + 1).fill(null);
        this.fact = Array(n + 1).fill(null);
        this.ifact = Array(n + 1).fill(null);
        this.inv[0] = new ModInt(1);
        this.inv[1] = new ModInt(1);
        this.fact[0] = new ModInt(1);
        this.ifact[0] = new ModInt(1);
        for (let i = 1; i <= n; i++) {
            if (i > 2) {
                this.inv[i] = this.inv[MOD % i].neg().mul(new ModInt(Math.floor(MOD / i)));
            } else if (i === 2) {
                this.inv[i] = new ModInt((MOD + 1) >> 1);
            }
            this.fact[i] = new ModInt(i).mul(this.fact[i - 1]);
            this.ifact[i] = this.inv[i].mul(this.ifact[i - 1]);
        }
    }

    factAt(n) {
        return this.fact[n];
    }

    invAt(x) {
        return this.inv[x];
    }

    ifactAt(x) {
        return this.ifact[x];
    }

    comb(n, k) {
        if (!(k <= n)) return new ModInt(0);
        return this.fact[n].mul(this.ifact[k]).mul(this.ifact[n - k]);
    }
}

// ---------- end ModInt ----------

function run(input) {
    const iter = input.trim().split(/\s+/);
    let idx = 0;
    const next = () => iter[idx++];

    const nStr = next();
    const nBig = BigInt(nStr);
    const m = parseInt(next(), 10);

    let t = SquareMatrix.identity(m);
    let s = SquareMatrix.zero(m);

    for (let i = 1; i < m; i++) {
        s.set_at(i - 1, i, ModInt.one());
    }
    s.set_at(m - 1, 0, ModInt.one());
    s.set_at(m - 1, m - 1, ModInt.one());

    let n = nBig;
    while (n > 0n) {
        if ((n & 1n) === 1n) {
            t = t.mul(new SquareMatrix(s.n, s.a.slice()));
        }
        s = new SquareMatrix(s.n, s.a.slice()).mul(s);
        n >>= 1n;
    }

    const ans = t.get_at(m - 1, m - 1);
    console.log(ans.toString());
}

